import {DAYS,SHORT_DAYS,ROOMS,defaultState} from './data.js';
import {makeSharedSupabaseClient,loginUrl,hasSharedSession,supportedHost} from './sso.js';
const CFG=window.SMART_AC_CONFIG||{};
const PAGE=document.body.dataset.page||'dashboard';
const STORAGE_KEY='smart-ac-kampus-full-demo-v1';
const $=(s,root=document)=>root.querySelector(s);
const $$=(s,root=document)=>[...root.querySelectorAll(s)];
const fmt=(n,d=1)=>Number(n||0).toFixed(d);
const escapeHtml=v=>String(v??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;');
const clamp=(v,lo,hi)=>Math.max(lo,Math.min(hi,v));
const localRead=()=>{try{return JSON.parse(localStorage.getItem(STORAGE_KEY)||'null')}catch{return null}};
const state={...defaultState(),weather:null,weatherSource:'memuat',remoteId:'A101-1',selectedRoom:null,previewDay:null,previewHour:null,scheduleDay:null,hmiTab:'overview',logFilter:'Semua',mode:'demo',plcMap:{},plcConnected:false,plcSocket:null,plcSelectedId:null,supabase:null,user:null,memberRole:null,weatherFetchAt:null,lastError:null,authBusy:false};
Object.assign(state,localRead()||{});
state.weather=null;state.weatherSource='memuat';state.supabase=null;state.user=null;state.memberRole=null;state.mode='demo';state.authBusy=false;
const timeFormat=(dt=new Date())=>new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Jakarta',hour:'2-digit',minute:'2-digit',hour12:false}).format(dt);
const localParts=(dt=new Date())=>{
  const parts=Object.fromEntries(new Intl.DateTimeFormat('en-US',{timeZone:'Asia/Jakarta',weekday:'short',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(dt).map(x=>[x.type,x.value]));
  const dw=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].indexOf(parts.weekday);
  return {day:dw,dayOfMonth:+parts.day,month:+parts.month,year:+parts.year,hour:+parts.hour,minute:+parts.minute,hhmm:`${parts.hour}:${parts.minute}`,date:`${parts.year}-${parts.month}-${parts.day}`};
};
const weekDay=()=>localParts().day;
const currentHour=()=>localParts().hour;
const normalizeClock=t=>String(t||'').slice(0,5);
const mins=t=>{const [h,m]=normalizeClock(t).split(':').map(Number);return h*60+(m||0)};
const currentMinutes=()=>{const t=localParts();return t.hour*60+t.minute};
function save(){if(state.mode==='demo'){try{localStorage.setItem(STORAGE_KEY,JSON.stringify({units:state.units,rooms:state.rooms,schedules:state.schedules,settings:state.settings,logs:state.logs.slice(0,160),alerts:state.alerts,remoteId:state.remoteId,selectedRoom:state.selectedRoom,scheduleDay:state.scheduleDay,hmiTab:state.hmiTab}))}catch{}}}
function navUrl(page){if(location.protocol==='file:'||location.hostname==='localhost'||location.hostname==='127.0.0.1')return `../${page}/index.html`;return CFG.domains?.[page]||`https://${page}.penyelamatharimu.my.id`}
function findRoom(code){return state.rooms.find(r=>r.code===code)||ROOMS.find(r=>r.code===code)}
function findUnit(id){return state.units.find(u=>u.id===id)}
function unitsOf(room){return state.units.filter(u=>u.room_code===room)}
function schedulesOn(day){return state.schedules.filter(s=>s.active!==false&&Number(s.day_of_week)===Number(day)).sort((a,b)=>mins(a.starts_at)-mins(b.starts_at))}
function schedulesIn(room,day,minute){return schedulesOn(day).filter(s=>s.room_code===room&&minute>=mins(s.starts_at)&&minute<mins(s.ends_at))}
function inSchedule(room,day,minute=0){return schedulesIn(room,day,minute)[0]||null}
function occupant(room,day,minute){const s=inSchedule(room,day,minute);return s?Number(s.attendees)||0:0}
const weatherUrl=`https://api.open-meteo.com/v1/forecast?latitude=${CFG.latitude??-6.1177}&longitude=${CFG.longitude??106.1539}&current=temperature_2m,relative_humidity_2m,weather_code,wind_speed_10m&hourly=temperature_2m,relative_humidity_2m,precipitation_probability,weather_code&timezone=Asia%2FJakarta&forecast_days=3`;
function simulatedOutdoor(hour=currentHour()){return Math.round((27.4+5.1*Math.sin((hour-7)*Math.PI/12)+.8*Math.sin(hour*1.7))*10)/10}
function weatherAt(hour=currentHour(),date=null){if(state.weather?.hourly?.time?.length){const day=date||localParts().date;const key=`${day}T${String(hour).padStart(2,'0')}:00`;let i=state.weather.hourly.time.findIndex(x=>x.startsWith(key));if(i<0)i=state.weather.hourly.time.findIndex(x=>x.endsWith(`T${String(hour).padStart(2,'0')}:00`));if(i>=0){return {temp:state.weather.hourly.temperature_2m[i],humidity:state.weather.hourly.relative_humidity_2m[i],rain:state.weather.hourly.precipitation_probability[i],code:state.weather.hourly.weather_code[i],simulated:false}}}return {temp:simulatedOutdoor(hour),humidity:68,rain:28,code:2,simulated:true}}
function outsideNow(){return state.weather?.current?.temperature_2m??weatherAt().temp}
function conditionName(code){if(code===0)return 'Cerah';if(code<=3)return 'Berawan';if(code<=48)return 'Berkabut';if(code<=67)return 'Hujan';if(code<=82)return 'Hujan deras';if(code>=95)return 'Badai petir';return 'Berawan'}
function conditionIcon(code){if(code===0)return '☀️';if(code<=3)return '⛅';if(code<=48)return '🌫️';if(code<=67)return '🌦️';if(code>=95)return '⛈️';return '🌧️'}
function adaptiveSetpoint(out,base=24){if(!state.settings.adaptive_weather)return clamp(base,22,27);return clamp(Number(base)+(out<28?1:out>=34?-1:0),22,27)}
function simulatedRoomTemp(room,unit,day=weekDay(),hour=currentHour(),out=weatherAt(hour).temp){const live=unit&&state.plcConnected&&state.plcMap?.[unit.id];if(live && Number(day)===weekDay() && Number(hour)===currentHour())return Number(live.roomTemp);const occupancy=occupant(room.code,day,hour*60);const now=localParts();const predicted=unit?.control_mode==='AUTO'&&state.settings.automation_enabled&&(hour!==now.hour||day!==now.day);const planned=state.settings.operating_days.includes(day)&&hour*60>=mins(state.settings.opening_time)&&hour*60<mins(state.settings.closing_time)&&schedulesOn(day).some(s=>s.room_code===room.code&&hour*60>=mins(s.starts_at)-state.settings.prestart_minutes&&hour*60<mins(s.ends_at)+state.settings.postend_minutes);const active=room.is_24h?unit?.power_on:(predicted?planned:unit?.power_on);const target=Number(unit?.target_temp||24);const harmonic=.25*Math.sin(hour*1.3+room.code.charCodeAt(2));const base=active?target+Math.max(0,out-target)*.095+occupancy*.011:out-1.8+occupancy*.018;return clamp(base+Number(room.heat_offset||0)+harmonic,20,39.5)}
function getTemp(room,day=weekDay(),hour=currentHour()){const us=unitsOf(room.code);return simulatedRoomTemp(room,us[0],day,hour)}
function watt(unit){const live=state.plcConnected&&state.plcMap?.[unit.id];if(live)return Math.round(Number(live.powerKw)*1000);return unit.power_on?Math.round((unit.power_kw||1.55)*1000*(.55+Math.max(0,outsideNow()-unit.target_temp)*.045)):0}
function fmtEvent(t){return new Intl.DateTimeFormat('id-ID',{timeZone:'Asia/Jakarta',day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'}).format(new Date(t))}
function logEvent(kind,message,source='Operator'){state.logs.unshift({id:globalThis.crypto?.randomUUID?.()||String(Date.now()+Math.random()),kind,source,message,created_at:new Date().toISOString()});save()}
function toast(msg,type='success'){const host=$('#toasts');if(!host)return;const el=document.createElement('div');el.className=`toast ${type==='error'?'error':''}`;el.textContent=msg;host.append(el);setTimeout(()=>el.remove(),4700)}
function isCloud(){return state.mode==='cloud'}
function canEdit(){return !isCloud()||(['admin','operator'].includes(state.memberRole)&&!!state.user)}
function loggedAs(){return isCloud()?(state.user?.email||'Belum masuk'):'Operator'}
function hasWeather(){return state.weatherSource==='Open-Meteo'}
function weatherStatusText(){return hasWeather()?`Serang ${fmt(outsideNow())}°C`:state.weatherSource==='memuat'?'Memuat cuaca Serang':'Cuaca belum tersedia'}
function headerNav(){
  const pages=[['dashboard','Dashboard'],['ac','HMI Gedung'],['remote','Remote AC']];
  return `<nav class="nav" aria-label="Navigasi utama">${pages.map(([p,label])=>`<a class="${PAGE===p?'active':''}" ${PAGE===p?'aria-current="page"':''} href="${navUrl(p)}">${label}</a>`).join('')}</nav>`;
}
function headerAuth(){
  return `<span class="db-connection"><i class="live-dot"></i><span id="nav-mode">Database aktif</span></span><div class="auth-area"><span class="user-tag" title="${escapeHtml(loggedAs())}">${escapeHtml(loggedAs())}</span><button class="link-btn" data-action="logout">Keluar</button></div>`;
}
function header(){
  const labels={dashboard:['DASHBOARD MONITORING','Analitik & energi'],ac:['HMI GEDUNG A','Denah & otomatisasi'],remote:['REMOTE AC','Panel kendali digital']};
  const current=labels[PAGE]||labels.dashboard;
  return `<header class="topbar topbar-unified">
    <div class="unified-main">
      <a class="unified-brand" href="${navUrl('dashboard')}" aria-label="Smart AC Kampus — Beranda">
        <span class="unified-logo" aria-hidden="true">❄</span>
        <span class="unified-brand-copy"><strong>SMART AC <span>KAMPUS</span></strong><small>BY RZKY STUDIO</small></span>
      </a>
      ${headerNav()}
      <div class="unified-utilities">
        <span class="unified-weather"><i aria-hidden="true">◉</i><span id="nav-weather">${weatherStatusText()}</span></span>
        <span class="header-clock mono" id="nav-clock">${timeFormat()} WIB</span>
        ${headerAuth()}
      </div>
    </div>
    <div class="unified-subheader">
      <div class="unified-context"><span class="unified-context-dot" aria-hidden="true"></span><strong>${current[0]}</strong><span class="unified-context-sep">/</span><span>${current[1]}</span></div>
      <span class="unified-context-location">GEDUNG A <i>•</i> SERANG, BANTEN</span>
    </div>
  </header>`;
}
function pageTitle(title,desc,tools=''){return `<div class="page-title"><div><div class="eyebrow">SMART BUILDING · GEDUNG A · KOTA SERANG</div><h1>${title}</h1><p>${desc}</p></div><div class="title-badges">${tools}</div></div>`}
function alarmStrip(){const hot=state.rooms.filter(r=>getTemp(r)>31&&!r.is_24h).length;return `<div class="alarm-strip"><span class="alarm-chip">${hot}</span><span class="alarm-chip orange">${state.units.filter(u=>u.control_mode==='MANUAL').length}</span><span class="alarm-chip yellow">${state.units.filter(u=>u.power_on&&!inSchedule(u.room_code,weekDay(),currentMinutes())&&!findRoom(u.room_code)?.is_24h).length}</span><span class="alarm-message">${hot?`Perhatian: ${hot} ruangan memiliki estimasi suhu >31°C.`:'Seluruh estimasi suhu ruangan berada di bawah batas peringatan.'} · <b>Indikator suhu dihitung dari model estimasi.</b></span><button class="btn sm" data-action="ack">ACK semua</button></div>`}
function temperatureDescription(temp){
  const level=temperatureLevel(temp);
  return ({cool:'Dingin',comfortable:'Nyaman',moderate:'Sedang',warm:'Hangat',hot:'Panas'})[level];
}
function dashboardRoomCard(room){
  const temp=getTemp(room);
  const level=temperatureLevel(temp);
  const units=unitsOf(room.code);
  const on=units.filter(u=>u.power_on).length;
  const powerState=on===0?'Mati':on===units.length?'Menyala':`${on}/${units.length} ON`;
  const pct=clamp(((temp-20)/15)*100,0,100);
  return `<article class="room-insight" aria-label="Ruangan ${escapeHtml(room.code)}, ${fmt(temp)} derajat Celsius estimasi, ${temperatureDescription(temp)}, ${on} dari ${units.length} AC menyala">
    <div class="room-insight-heading"><div class="room-insight-identity"><span class="room-insight-icon">▦</span><div><b>${escapeHtml(room.code)}</b><small>${escapeHtml(room.name)}</small></div></div><span class="room-insight-power ${on?'on':'off'}"><i></i>${powerState}</span></div>
    <div class="room-insight-center"><div class="room-insight-temperature temp-${level}">${fmt(temp)}<span>°C</span></div><div class="room-insight-condition"><b>${temperatureDescription(temp)}</b><small>Suhu estimasi</small></div></div>
    <div class="room-insight-thermometer" aria-label="Skala suhu 20 hingga 35 derajat Celsius"><div class="room-insight-thermometer-fill temp-${level}" style="width:${pct.toFixed(1)}%"></div><i class="room-insight-needle" style="left:${clamp(pct,2,98).toFixed(1)}%"></i></div>
    <div class="room-insight-range"><span>20°C</span><span>35°C</span></div>
  </article>`;
}
function dashboardHtml(){const on=state.units.filter(u=>u.power_on).length,kw=state.units.reduce((a,u)=>a+watt(u),0)/1000,avg=state.rooms.reduce((s,r)=>s+getTemp(r),0)/state.rooms.length,occupancy=state.rooms.reduce((s,r)=>s+occupant(r.code,weekDay(),currentMinutes()),0);return `${pageTitle('Dashboard Monitoring','Ringkasan energi, kondisi ruangan, cuaca live, dan kegiatan kuliah.',`<span class="pill blue">📍 Serang, Banten</span>`)}<div class="stats"><div class="card stat"><div class="stat-label">Unit AC Aktif</div><span class="stat-icon">❄</span><div class="stat-val">${on}<span class="subtle" style="font-size:17px"> / ${state.units.length}</span></div><div class="stat-foot">Status berdasarkan pengaturan unit</div><div class="stat-accent"></div></div><div class="card stat"><div class="stat-label">Daya Terestimasi</div><span class="stat-icon">⚡</span><div class="stat-val">${fmt(kw,2)}<span style="font-size:15px"> kW</span></div><div class="stat-foot">Perhitungan estimasi konsumsi</div><div class="stat-accent orange"></div></div><div class="card stat"><div class="stat-label">Rata-rata Suhu Ruang</div><span class="stat-icon">🌡</span><div class="stat-val">${fmt(avg)}<span style="font-size:15px">°C</span></div><div class="stat-foot">Estimasi untuk ${state.rooms.length} ruangan</div><div class="stat-accent green"></div></div><div class="card stat"><div class="stat-label">Mahasiswa Terjadwal</div><span class="stat-icon">♙</span><div class="stat-val">${occupancy}</div><div class="stat-foot">Estimasi berdasarkan jadwal aktif</div><div class="stat-accent purple"></div></div></div><div class="two-col"><div class="card"><div class="section-head"><div><div class="eyebrow">ANALITIK TEMPERATUR</div><h2>Perubahan Suhu per Jam</h2><p>Tren suhu luar dan estimasi suhu dalam ruangan</p></div><select class="select" id="chart-room" aria-label="Pilih ruangan">${state.rooms.map(r=>`<option value="${r.code}" ${(state.selectedRoom||'A101')===r.code?'selected':''}>${r.code}</option>`).join('')}</select></div><div id="main-chart">${makeChart(state.selectedRoom||'A101')}</div><div class="legend"><span><i></i>Ruangan · estimasi</span><span><i class="orange"></i>Luar · ${hasWeather()?'Open-Meteo':'perkiraan model'}</span></div></div><div class="card"><div class="section-head"><div><div class="eyebrow">LIVE WEATHER · SERANG</div><h2>Cuaca Kota Serang</h2><p>Cuaca saat ini dan prakiraan tiap jam</p></div><div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap"><span class="pill ${hasWeather()?'green':'amber'}">${hasWeather()?'API LIVE':'TIDAK TERSEDIA'}</span><button class="btn sm" data-action="refresh-weather" aria-label="Perbarui cuaca">↻ Perbarui</button></div></div>${weatherHtml()}</div></div><div class="two-col equal"><div class="card"><div class="section-head"><div><div class="eyebrow">AGENDA AKADEMIK</div><h2>Kuliah Hari Ini — ${DAYS[weekDay()]}</h2><p>Jadwal otomatis Senin–Sabtu</p></div><a class="btn sm" href="${navUrl('ac')}">Kelola jadwal ↗</a></div>${todayAgenda()}</div><div class="card"><div class="section-head"><div><div class="eyebrow">STATUS UNIT GEDUNG</div><h2>Ringkasan Ruangan</h2><p>Indikator kondisi ruangan dan status tiap unit AC</p></div><a class="btn sm" href="${navUrl('remote')}">Remote ↗</a></div><div class="room-insight-legend"><span><i class="key-on"></i> AC menyala</span><span><i class="key-off"></i> AC mati</span><span class="room-temp-legend">Suhu estimasi: <i class="key-cool"></i> Dingin <i class="key-moderate"></i> Sedang <i class="key-hot"></i> Panas</span></div><div class="room-insights-grid">${state.rooms.slice(0,8).map(dashboardRoomCard).join('')}</div></div></div>`}
function makeChart(code){const room=findRoom(code)||state.rooms[0],hours=Array.from({length:13},(_,i)=>6+i),x=i=>42+i*(610/12),y=v=>221-(v-20)*10.2;const inside=hours.map(h=>simulatedRoomTemp(room,unitsOf(room.code)[0],weekDay(),h,weatherAt(h).temp));const outside=hours.map(h=>weatherAt(h).temp);const path=a=>a.map((v,i)=>`${i?'L':'M'}${x(i).toFixed(1)},${y(v).toFixed(1)}`).join(' ');const filled=`${path(inside)} L${x(12)},221 L${x(0)},221 Z`;return `<svg class="chart" viewBox="0 0 690 265" role="img" aria-label="Grafik estimasi suhu luar dan dalam ruangan dari jam 06 hingga 18 WIB"><defs><linearGradient id="cg" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#4d9cec" stop-opacity=".24"/><stop offset="1" stop-color="#4d9cec" stop-opacity="0"/></linearGradient></defs>${[20,25,30,35,40].map(v=>`<line class="chart-grid" x1="42" y1="${y(v)}" x2="652" y2="${y(v)}"/><text class="chart-text" x="3" y="${y(v)+3}">${v}°C</text>`).join('')}<path d="${filled}" fill="url(#cg)"/><path d="${path(outside)}" fill="none" stroke="#eda254" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/><path d="${path(inside)}" fill="none" stroke="#328ee0" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>${inside.filter((_,i)=>i%2===0).map((v,j)=>`<circle cx="${x(j*2)}" cy="${y(v)}" r="3.3" fill="#328ee0" stroke="white" stroke-width="1.5"/>`).join('')}${hours.map((h,i)=>i%2===0?`<text class="chart-text" x="${x(i)-15}" y="249">${String(h).padStart(2,'0')}:00</text>`:'').join('')}</svg>`}
function weatherHtml(){const now=state.weather?.current;const hour=now?.temperature_2m??outsideNow();const code=now?.weather_code??2;const current=localParts();return `<div class="weather-feature"><div><div class="condition">${conditionName(code)} · ${hasWeather()?'Terbaru dari Open-Meteo':'Data cuaca tidak tersedia'}</div><div class="big">${hasWeather()?fmt(hour)+'°':'--'}</div><div class="condition">${hasWeather()?`Kelembapan ${now?.relative_humidity_2m??'-'}% · Angin ${now?.wind_speed_10m??'-'} km/j`:'Klik Perbarui untuk memuat kondisi terkini'}</div></div><div class="weather-icon">${conditionIcon(code)}</div></div><div class="weather-mini">${hasWeather()?Array.from({length:5},(_,i)=>{const upcoming=localParts(new Date(Date.now()+i*3600000));const h=upcoming.hour,w=weatherAt(h,upcoming.date);return `<div><span>${String(h).padStart(2,'0')}.00</span><b>${conditionIcon(w.code)}</b><b>${fmt(w.temp,0)}°</b></div>`}).join(''):`<div class="empty" style="grid-column:1/-1">Prakiraan per jam belum tersedia.</div>`}</div><p class="weather-footer">Sumber cuaca: ${hasWeather()?'Open-Meteo · Kota Serang, Banten':'Open-Meteo · pembaruan sedang tidak tersedia'}. Data temperatur ruangan merupakan hasil estimasi.</p>`}
function todayAgenda(){const day=weekDay();const lines=schedulesOn(day);return !lines.length?`<div class="empty">Tidak ada jadwal kuliah hari ini.</div>`:`<div class="table-wrap"><table class="table"><thead><tr><th>Jam</th><th>Mata kuliah</th><th>Ruang</th><th>Status</th></tr></thead><tbody>${lines.slice(0,7).map(s=>{const at=currentMinutes(),active=at>=mins(s.starts_at)&&at<mins(s.ends_at);return `<tr><td class="mono">${normalizeClock(s.starts_at)}–${normalizeClock(s.ends_at)}</td><td><strong>${escapeHtml(s.course)}</strong></td><td>${escapeHtml(s.room_code)}</td><td><span class="status ${active?'on':'off'}">${active?'Berlangsung':'Terjadwal'}</span></td></tr>`}).join('')}</tbody></table></div>`}
function hmiHtml(){if(state.previewDay===null)state.previewDay=weekDay()||1;if(state.previewHour===null)state.previewHour=currentHour();return `${pageTitle('HMI Gedung A','Denah gedung, panel kontrol unit, jadwal kuliah, dan riwayat aktivitas.',`<span class="pill blue">◷ Jam operasi ${state.settings.opening_time}–${state.settings.closing_time}</span>`)}${alarmStrip()}<div class="hmi-subtabs"><button class="hmi-tab ${state.hmiTab==='overview'?'active':''}" data-tab="overview">Overview Denah</button><button class="hmi-tab ${state.hmiTab==='automation'?'active':''}" data-tab="automation">Jadwal & Otomasi</button><button class="hmi-tab ${state.hmiTab==='events'?'active':''}" data-tab="events">Log Event</button><span class="hmi-time-status">${DAYS[weekDay()]} · ${timeFormat()} WIB · ${state.settings.automation_enabled?'Otomasi AKTIF':'Otomasi NONAKTIF'}</span></div><div id="hmi-content">${hmiContent()}</div>`}
function hmiContent(){if(state.hmiTab==='automation')return automationHtml();if(state.hmiTab==='events')return logsHtml();return overviewHtml()}
function overviewHtml(){return `<div class="card" style="padding:11px 15px;margin-bottom:14px;display:flex;align-items:center;gap:10px;flex-wrap:wrap"><b style="font-size:11px;color:#617a95">PRATINJAU SUHU PER JAM</b><select id="preview-day" class="select">${DAYS.slice(1).map((d,i)=>`<option value="${i+1}" ${state.previewDay===i+1?'selected':''}>${d}</option>`).join('')}</select><input aria-label="Pilih jam" id="preview-hour" type="range" min="0" max="23" value="${state.previewHour}" style="accent-color:#278ce1;min-width:130px;flex:1"><strong class="mono">${String(state.previewHour).padStart(2,'0')}:00</strong><span class="pill blue">Luar ${fmt(weatherAt(state.previewHour).temp)}°C · ${hasWeather()?'API':'estimasi'}</span><button class="btn sm" data-action="preview-now">↻ Sekarang</button></div><div class="hmi-layout"><div class="industrial"><div class="industrial-title">DENAH GEDUNG A — KLIK UNIT UNTUK FACEPLATE</div><div class="floorplan-overflow"><div class="floorplan-inner">${[3,2,1].map(f=>`<div class="floor-row"><div class="floor-name">LT ${f}</div><div class="floor-grid f${f}">${state.rooms.filter(r=>r.floor===f).map(r=>roomTile(r)).join('')}</div></div>`).join('')}</div></div><div class="plan-bottom" aria-label="Legenda status dan temperatur"><span class="legend-label">STATUS AC</span><span class="map-key"><i class="map-key-dot key-on"></i> Menyala</span><span class="map-key"><i class="map-key-dot key-off"></i> Mati</span><span class="map-key"><i class="map-key-dot key-manual"></i> Manual</span><span class="legend-label temp-scale-label">SUHU ESTIMASI</span><span class="map-key"><i class="map-key-dot key-cool"></i> ≤22° dingin</span><span class="map-key"><i class="map-key-dot key-comfort"></i> 23–24° nyaman</span><span class="map-key"><i class="map-key-dot key-moderate"></i> 25–26° sedang</span><span class="map-key"><i class="map-key-dot key-warm"></i> 27–29° hangat</span><span class="map-key"><i class="map-key-dot key-hot"></i> ≥30° panas</span></div></div><div class="side-stack"><div class="industrial" id="faceplate">${faceplateHtml()}</div><div class="industrial"><div class="industrial-title">KONTROL GRUP</div><label class="field-label">Cakupan</label><select id="group-floor" class="select full"><option value="all">Semua lantai</option><option value="3">Lantai 3</option><option value="2">Lantai 2</option><option value="1">Lantai 1</option></select><div class="group-grid"><button class="btn" data-action="group-on">Semua ON</button><button class="btn" data-action="group-off">Semua OFF</button><button class="btn" data-action="group-auto">Semua AUTO</button><button class="btn" data-action="group-manual">Semua MANUAL</button></div><p class="help-line" style="margin-top:12px">Ruang server A205 (24 jam) dikecualikan dari kontrol grup.</p></div><div class="industrial"><div class="industrial-title">STATUS SISTEM</div><div class="toggle-row"><span>AC Aktif</span><strong>${state.units.filter(u=>u.power_on).length}/${state.units.length}</strong></div><div class="toggle-row"><span>Otomasi</span><span class="status ${state.settings.automation_enabled?'on':'off'}">${state.settings.automation_enabled?'ON':'OFF'}</span></div><div class="toggle-row"><span>Cuaca Serang</span><span class="status ${hasWeather()?'on':'manual'}">${hasWeather()?'LIVE API':'TIDAK TERSEDIA'}</span></div></div></div></div>`}
function temperatureLevel(temp){
  // Skala warna berdasarkan estimasi suhu ruang (°C), bukan data sensor fisik.
  if(temp<=22) return 'cool';       // hijau - dingin
  if(temp<=24) return 'comfortable';// hijau kebiruan - nyaman
  if(temp<=26) return 'moderate';   // kuning - sedang
  if(temp<30) return 'warm';        // oranye - hangat
  return 'hot';                     // merah - panas (30°C ke atas)
}
function roomTile(room){
  const us=unitsOf(room.code);
  const onCount=us.filter(u=>u.power_on).length;
  const isOn=onCount>0;
  const temp=simulatedRoomTemp(room,us[0],state.previewDay,state.previewHour,weatherAt(state.previewHour).temp);
  const level=temperatureLevel(temp);
  const people=occupant(room.code,state.previewDay,state.previewHour*60);
  const status=onCount===0?'AC OFF':onCount===us.length?'AC ON':`${onCount}/${us.length} ON`;
  return `<button class="room-tile ${isOn?'room-on':'room-off'} ${state.selectedRoom===room.code?'selected':''} ${room.is_24h?'server':''}"
    data-action="room" data-id="${room.code}" aria-label="${escapeHtml(room.code)}: ${status}, suhu estimasi ${fmt(temp)} derajat Celsius. Pilih untuk membuka faceplate.">
      <div class="room-topline"><b class="room-code">${escapeHtml(room.code)}</b><span class="room-power ${isOn?'on':'off'}"><i></i>${status}</span></div>
      <span class="room-type">${escapeHtml(room.name)}</span>
      <div class="temp-badge temp-${level}" title="Suhu ruangan: estimasi, bukan pembacaan sensor fisik">
        <span class="temp-number">${fmt(temp)}°C</span><span class="temp-caption">SUHU EST.</span>
      </div>
      <span class="room-info">RH ≈55% · 👥 ${people}</span>
      ${!people&&!room.is_24h?`<span class="room-info">Ruangan kosong</span>`:''}
      <div class="unit-chips">${us.map(u=>`<span class="unit-chip ${u.power_on?'on':'off'} ${u.control_mode==='MANUAL'?'manual':''}" title="${escapeHtml(u.id)} · ${u.power_on?'ON':'OFF'} · ${escapeHtml(u.control_mode)}">${escapeHtml(u.label)}<small>${u.power_on?'ON':'OFF'} · ${u.target_temp}°</small></span>`).join('')}</div>
    </button>`;
}
function faceplateHtml(){const room=findRoom(state.selectedRoom);if(!room)return `<h2>Pilih unit</h2><p class="subtle" style="font-size:12px">Klik salah satu ruangan dalam denah untuk membuka faceplate AC dan mengatur unitnya.</p>`;const us=unitsOf(room.code);return `<div class="industrial-title">FACEPLATE · ${escapeHtml(room.code)}</div><h2>${escapeHtml(room.name)}</h2><p class="micro">Suhu estimasi: ${fmt(getTemp(room,state.previewDay,state.previewHour))}°C · ${occupant(room.code,state.previewDay,state.previewHour*60)} peserta</p>${us.map(u=>`<div class="face-unit"><div class="face-head"><strong>${escapeHtml(u.id)}</strong><span class="status ${u.power_on?'on':'off'}">${u.power_on?'ON':'OFF'} · ${u.control_mode}</span></div><div class="face-actions"><button class="btn sm ${u.power_on?'green':''}" data-action="power" data-id="${u.id}" ${!canEdit()?'disabled':''}>⏻ ${u.power_on?'OFF':'ON'}</button><button class="btn sm" data-action="temperature" data-id="${u.id}" data-value="-1" ${!canEdit()?'disabled':''}>−</button><strong class="mono">${u.target_temp}°C</strong><button class="btn sm" data-action="temperature" data-id="${u.id}" data-value="1" ${!canEdit()?'disabled':''}>+</button><button class="btn sm" data-action="toggle-mode" data-id="${u.id}" ${!canEdit()?'disabled':''}>${u.control_mode==='AUTO'?'Manual':'Otomatis'}</button></div></div>`).join('')}<p class="help-line">Perubahan pada unit digital mengaktifkan pengaturan manual selama ${state.settings.override_minutes} menit sebelum jadwal otomatis kembali berjalan.</p>`}
function automationHtml(){const s=state.settings,authorized=canEdit();return `<div class="industrial"><div class="industrial-title">ATURAN OTOMATIS · SENIN–SABTU</div><div class="form-columns"><div><label class="toggle-row"><span>Otomasi aktif</span><input type="checkbox" data-setting="automation_enabled" ${s.automation_enabled?'checked':''} ${!authorized?'disabled':''}></label><label class="toggle-row"><span>Adaptasi suhu mengikuti cuaca Serang</span><input type="checkbox" data-setting="adaptive_weather" ${s.adaptive_weather?'checked':''} ${!authorized?'disabled':''}></label><label class="toggle-row"><span>Aktif pada hari Senin–Sabtu</span><span class="status on">Senin—Sabtu</span></label><p class="help-line" style="margin-top:18px">Kelola jadwal kuliah dan parameter otomatisasi ruangan. Sinkronisasi antarsitus memerlukan sambungan pusat data.</p></div><div><label class="toggle-row"><span>Nyala sebelum kelas (menit)</span><input class="input" type="number" min="0" max="60" style="width:80px" data-setting="prestart_minutes" value="${s.prestart_minutes}" ${!authorized?'disabled':''}></label><label class="toggle-row"><span>Jeda mati setelah kelas (menit)</span><input class="input" type="number" min="0" max="60" style="width:80px" data-setting="postend_minutes" value="${s.postend_minutes}" ${!authorized?'disabled':''}></label><label class="toggle-row"><span>Override manual (menit)</span><input class="input" type="number" min="5" max="240" style="width:80px" data-setting="override_minutes" value="${s.override_minutes}" ${!authorized?'disabled':''}></label><label class="toggle-row"><span>Setpoint default (°C)</span><input class="input" type="number" min="22" max="27" style="width:80px" data-setting="default_setpoint" value="${s.default_setpoint}" ${!authorized?'disabled':''}></label></div></div><div class="subhead">JAM OPERASIONAL GEDUNG</div><div class="table-wrap"><table class="table"><thead><tr><th>Hari</th><th>Status</th><th>Mulai</th><th>Selesai</th></tr></thead><tbody>${DAYS.slice(1).map(d=>`<tr><td>${d}</td><td><span class="status on">Aktif</span></td><td>${normalizeClock(s.opening_time)}</td><td>${normalizeClock(s.closing_time)}</td></tr>`).join('')}<tr><td>Minggu</td><td><span class="status off">Libur</span></td><td>—</td><td>—</td></tr></tbody></table></div><div class="subhead">JADWAL KULIAH</div><div class="days-tabs">${DAYS.slice(1).map((d,i)=>`<button class="${(state.scheduleDay??(weekDay()||1))===i+1?'active':''}" data-action="day" data-value="${i+1}">${d}</button>`).join('')}</div><div style="display:flex;gap:10px;justify-content:space-between;align-items:center;margin-bottom:12px;flex-wrap:wrap"><p class="micro" style="margin:0">Tambahkan atau hapus jadwal sesuai kalender perkuliahan. Hari Minggu tidak memiliki jadwal.</p><button class="btn primary sm" data-action="add-schedule" ${!authorized?'disabled':''}>＋ Tambah Mata Kuliah</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Waktu</th><th>Mata kuliah</th><th>Ruangan</th><th>Peserta</th><th>Setpoint</th><th>Aksi</th></tr></thead><tbody>${schedulesOn(state.scheduleDay??(weekDay()||1)).map(s=>`<tr><td class="mono">${normalizeClock(s.starts_at)}–${normalizeClock(s.ends_at)}</td><td><strong>${escapeHtml(s.course)}</strong></td><td>${escapeHtml(s.room_code)}</td><td>${s.attendees}</td><td>${s.target_temp}°C</td><td><button class="btn sm danger" data-action="delete-schedule" data-id="${escapeHtml(s.id)}" ${!authorized?'disabled':''}>Hapus</button></td></tr>`).join('')||`<tr><td colspan="6" class="empty">Belum ada jadwal hari ini.</td></tr>`}</tbody></table></div><p class="help-line" style="margin-top:14px">Perhitungan setpoint adaptif: suhu luar ≥34°C → setpoint dasar −1°C; luar &lt;28°C → setpoint dasar +1°C. Rentang setpoint 22–27°C.</p></div>`}
function logsHtml(){const list=state.logs.filter(l=>state.logFilter==='Semua'||l.kind===state.logFilter).map(l=>({...l,source:String(l.source||'Sistem').replaceAll(' Demo',''),message:String(l.message||'').replace('Simulasi Smart AC Kampus siap. Sensor fisik belum terhubung.','Sistem monitoring siap digunakan.').replace('Jadwal kuliah Senin–Sabtu tersedia untuk pengujian.','Jadwal kuliah Senin–Sabtu telah dimuat.')}));return `<div class="industrial"><div class="industrial-title">LOG EVENT / AUDIT TRAIL</div><div class="days-tabs">${['Semua','Otomasi','Operator','Alarm','Sistem'].map(k=>`<button data-action="logfilter" data-value="${k}" class="${state.logFilter===k?'active':''}">${k}</button>`).join('')}</div><div class="table-wrap" style="max-height:590px;overflow:auto"><table class="table"><thead><tr><th style="min-width:150px">Waktu (WIB)</th><th>Sumber</th><th>Jenis</th><th>Pesan</th></tr></thead><tbody>${list.map(l=>`<tr><td class="mono">${fmtEvent(l.created_at)}</td><td>${escapeHtml(l.source||'Sistem')}</td><td>${escapeHtml(l.kind)}</td><td>${escapeHtml(l.message)}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">Tidak ada event pada kategori ini.</td></tr>'}</tbody></table></div></div>`}
function remoteHtml(){const u=findUnit(state.remoteId)||state.units[0],r=findRoom(u.room_code),temp=simulatedRoomTemp(r,u),w=watt(u),override=u.manual_override_until?new Date(u.manual_override_until).getTime()>Date.now():false;return `${pageTitle('Remote AC Digital','Pengaturan AC per unit, mode operasi, suhu target, dan kipas.',`<span class="pill green">✦ Gedung A · ${escapeHtml(r.name)}</span>`)}<div class="remote-layout"><div class="remote-side"><div class="dark-card"><div class="eyebrow">PILIH PERANGKAT</div><label for="remote-device" class="field-label">Ruangan & unit AC</label><select id="remote-device" class="select full">${state.units.map(x=>`<option value="${x.id}" ${x.id===u.id?'selected':''}>${x.id} — ${escapeHtml(findRoom(x.room_code)?.name)}</option>`).join('')}</select><div style="margin-top:10px"><span class="status ${u.power_on?'on':'off'}">● ${u.power_on?'MENYALA':'MATI'}</span> <span class="status ${u.control_mode==='MANUAL'?'manual':'on'}">${u.control_mode}</span></div><div class="divider"></div><div class="label-value"><span>Lokasi</span><strong>Gedung A / Lantai ${r.floor}</strong></div><div class="label-value"><span>Suhu ruangan</span><strong>${fmt(temp)}°C <small style="opacity:.6">estimasi</small></strong></div><div class="label-value"><span>Kelembapan</span><strong>≈55% (estimasi)</strong></div><div class="label-value"><span>Jadwal aktif</span><strong>${inSchedule(r.code,weekDay(),currentMinutes())?'Ada kelas':'Tidak ada'}</strong></div><div class="label-value"><span>Daya terestimasi</span><strong>${w} W</strong></div><div class="label-value"><span>Override</span><strong>${override?fmtEvent(u.manual_override_until):'Tidak aktif'}</strong></div></div><div class="dark-card"><h2>Perintah terakhir</h2><p>${escapeHtml(state.logs.find(l=>l.message?.includes(u.id))?.message||'Belum ada perintah pada unit ini.')}</p><p class="help-line">${isCloud()?'Perubahan disimpan pada pusat data untuk akses antarhalaman.':'Perubahan tersimpan pada browser ini. Untuk sinkronisasi antarwebsite, sambungkan pusat data.'}</p></div></div><div class="remote-control-wrap"><div class="remote-shell"><div class="remote-screen"><div class="screen-top"><span>${u.power_on?escapeHtml(u.hvac_mode||'COOL'):'STANDBY'}</span><span>FAN ${escapeHtml(u.fan_mode)}</span></div><div class="screen-temp">${u.power_on?u.target_temp:'--'}<sup>°C</sup></div><div class="screen-bottom"><span>Ruang ${fmt(temp)}°C</span>·<span>RH ~55%</span>·<span>${occupant(r.code,weekDay(),currentMinutes())} org</span></div><div class="screen-mode">${u.control_mode==='AUTO'?'AUTO-CTRL':'MANUAL-CTRL'} ${u.swing_on?'· SWING':''}</div></div><div class="remote-device-label">${escapeHtml(u.id)} · ${escapeHtml(r.name)} · 2 PK</div><div class="remote-device-detail">${w} W · ${u.control_mode==='MANUAL'?'Manual override':'Jadwal otomatis'} · Data estimasi</div><div class="remote-buttons"><button class="remote-button" data-action="cycle-control" data-id="${u.id}" ${!canEdit()?'disabled':''}>MODE</button><button class="remote-button power ${u.power_on?'active':'off'}" data-action="power" data-id="${u.id}" ${!canEdit()?'disabled':''}>⏻ POWER</button><button class="remote-button" data-action="fan" data-id="${u.id}" ${!canEdit()?'disabled':''}>FAN</button><button class="remote-button plusminus" data-action="temperature" data-id="${u.id}" data-value="-1" ${!canEdit()?'disabled':''}>−</button><button class="remote-button" data-action="swing" data-id="${u.id}" ${!canEdit()?'disabled':''}>SWING</button><button class="remote-button plusminus" data-action="temperature" data-id="${u.id}" data-value="1" ${!canEdit()?'disabled':''}>＋</button><button class="remote-button manual" data-action="toggle-mode" data-id="${u.id}" ${!canEdit()?'disabled':''}>Kontrol: ${u.control_mode} · ${u.control_mode==='AUTO'?'Alihkan MANUAL':'Kembali AUTO'}</button></div></div><p class="remote-device-foot">AUTO mengikuti jadwal dan cuaca setelah manual override habis. Perubahan POWER/temperatur/fan/swing mengaktifkan override selama ${state.settings.override_minutes} menit.</p></div></div>`}
function plcPanel(){
  const defaultUnit=PAGE==='remote'?state.remoteId:PAGE==='ac'?(state.selectedRoom?unitsOf(state.selectedRoom)[0]?.id:'A101-1'):(unitsOf(state.selectedRoom||'A101')[0]?.id||'A101-1');
  const chosen=state.units.some(u=>u.id===state.plcSelectedId)?state.plcSelectedId:defaultUnit;
  const deviceOptions=state.units.map(u=>`<option value="${escapeHtml(u.id)}" ${chosen===u.id?'selected':''}>${escapeHtml(u.id)} — ${escapeHtml(findRoom(u.room_code)?.name||u.room_code)}</option>`).join('');
  const p=state.plcMap?.[chosen];
  const wsLabel=state.plcConnected?'TERHUBUNG':(CFG.plcWsUrl?'MENGHUBUNGKAN':'BELUM DIKONFIGURASI');
  const regs=p?.registers||{};
  const regRows=[['%Q0.0','MASTER_POWER'],['%M0.0','AUTO_MODE'],['%Q0.1','COMP_OUT'],['%Q0.2','SWING_MTR'],['%Q0.3','ALM_TEMP'],['%MW10','SET_TEMP'],['%MW12','ACT_TEMP'],['%MW16','POWER_KW'],['%MW20','FAN_LVL']];
  return `<section class="card plc-panel" aria-label="Panel monitoring PLC">
   <div class="plc-head"><div><div class="eyebrow">PLC CONTROL · SCAN CYCLE 1 DETIK</div><h2>PLC Monitoring · ${escapeHtml(chosen||'AC')}</h2><p>Register PLC, status kompresor, dan temperatur ruangan</p></div><div class="plc-head-controls"><label class="plc-device-label" for="plc-unit-select">Pilih Unit AC<select id="plc-unit-select" class="select plc-unit-select" aria-label="Pilih unit AC untuk monitoring PLC">${deviceOptions}</select></label><span class="plc-connection ${state.plcConnected?'connected':''}">● ${wsLabel}</span></div></div>
   ${!p?`<div class="plc-unavailable">${CFG.plcWsUrl?'Menunggu telemetri PLC dari Cloudflare Workers.':'Isi plcWsUrl pada config.js untuk mengaktifkan backend PLC di Cloudflare Workers.'}</div>`:`
    <div class="plc-readings">
      <div class="plc-reading"><small>Suhu Ruangan (estimasi)</small><strong>${fmt(p.roomTemp)}°C</strong></div>
      <div class="plc-reading"><small>Target suhu</small><strong>${fmt(p.setpoint,0)}°C</strong></div>
      <div class="plc-reading"><small>Kompresor</small><strong class="${p.compressor?'plc-on':''}">${p.compressor?'ON':'OFF'}</strong></div>
      <div class="plc-reading"><small>Daya (estimasi)</small><strong>${fmt(p.powerKw,2)} kW</strong></div>
    </div>
    <div class="plc-unit-visual ${p.power?'powered':'off'}"><div class="plc-unit-shell"><div class="plc-unit-led">${p.power?fmt(p.setpoint,0)+'°C':'OFF'}</div><div class="plc-vent"><div class="plc-fan ${p.power?'spinning':''}">✺</div><div class="plc-louver ${p.swing?'swinging':''}"></div></div></div><div class="plc-wind ${p.compressor?'blowing':''}">❄　❄　❄</div></div>
    ${p.alarmHighTemp?'<div class="plc-alert">ALARM %Q0.3 · Suhu ruangan ≥ 30°C</div>':''}
    <div class="plc-registers">${regRows.map(([key,name])=>`<div><code>${key}</code><span>${name}</span><strong>${regs[key]??'—'}</strong></div>`).join('')}</div>`}
   
  </section>`;
}
function connectPlc(){
 const raw=String(CFG.plcWsUrl||'').trim();if(!raw)return;
 const url=raw.replace(/^https:\/\//,'wss://').replace(/^http:\/\//,'ws://');
 const start=()=>{
  const ws=new WebSocket(url);state.plcSocket=ws;
  ws.onopen=()=>{state.plcConnected=false;rerender();};
  ws.onmessage=e=>{try{const msg=JSON.parse(e.data);if(msg.type==='PLC_STATE'&&Array.isArray(msg.data)){
   state.plcConnected=Boolean(msg.connectedToDatabase);
   state.plcMap=state.plcConnected?Object.fromEntries(msg.data.map(x=>[x.unitId,x])):{};
   // The shared backend is authoritative for displayed power/setpoint status,
   // so HMI and Dashboard update even when Supabase Realtime is delayed.
   if(state.mode==='cloud'&&state.plcConnected){for(const p of msg.data){const u=state.units.find(x=>x.id===p.unitId);if(u){u.power_on=Boolean(p.power);u.target_temp=Number(p.setpoint);u.control_mode=p.autoMode?'AUTO':'MANUAL';u.fan_mode=p.fanMode;u.swing_on=Boolean(p.swing)}}}
  }}catch(err){console.warn('Invalid PLC packet',err)}};
  ws.onclose=()=>{state.plcConnected=false;rerender();setTimeout(start,4500)};
  ws.onerror=()=>{ws.close()};
 };
 start();
 setInterval(()=>{if(state.plcSocket?.readyState===WebSocket.OPEN)state.plcSocket.send(JSON.stringify({type:'PING'}))},20000);
 setInterval(()=>{if(state.plcConnected && (PAGE!=='ac'||state.hmiTab==='overview'))rerender()},3000);
}
function footerHtml(){return `<p class="foot-note">Smart AC by RZKY Studio</p>`}
function shell(){document.body.className=PAGE==='remote'?'remote-body':PAGE==='ac'?'hmi-body':'';$('#app').innerHTML=header()+`<main class="app-wrap" id="main">${PAGE==='dashboard'?dashboardHtml():PAGE==='ac'?hmiHtml():remoteHtml()}${plcPanel()}${footerHtml()}</main><div class="toast-stack" id="toasts" aria-live="polite"></div><div id="modal-root"></div>`}
function rerender(){const prior=$('#main');if(!prior)return shell();prior.innerHTML=(PAGE==='dashboard'?dashboardHtml():PAGE==='ac'?hmiHtml():remoteHtml())+plcPanel()+footerHtml();const clock=$('#nav-clock');if(clock)clock.textContent=timeFormat()+' WIB';const weather=$('#nav-weather');if(weather)weather.textContent=weatherStatusText();const live=$('#nav-mode');if(live)live.textContent='Database aktif'}
async function fetchWeather(){try{const ctl=new AbortController(),timer=setTimeout(()=>ctl.abort(),8000);let res;try{res=await fetch(weatherUrl,{signal:ctl.signal,cache:'no-store'})}finally{clearTimeout(timer)}if(!res.ok)throw Error('HTTP '+res.status);const data=await res.json();if(!data.current||!data.hourly)throw Error('Data cuaca tidak lengkap');state.weather=data;state.weatherSource='Open-Meteo';state.weatherFetchAt=new Date().toISOString();rerender()}catch(e){state.weatherSource='tidak tersedia';state.lastError=e.message;rerender()}}
function applyLocalAuto(){if(isCloud()||!state.settings.automation_enabled)return;const now=localParts(),minute=now.hour*60+now.minute,s=state.settings;let changes=0;for(const u of state.units){const room=findRoom(u.room_code);if(!room||room.is_24h)continue;if(u.manual_override_until&&new Date(u.manual_override_until).getTime()>Date.now())continue;if(u.control_mode==='MANUAL'&&u.manual_override_until&&new Date(u.manual_override_until).getTime()<=Date.now()){u.control_mode='AUTO';u.manual_override_until=null;changes++}const open=s.operating_days.includes(now.day)&&minute>=mins(s.opening_time)&&minute<mins(s.closing_time);const active=open&&schedulesOn(now.day).some(q=>q.room_code===room.code&&minute>=mins(q.starts_at)-Number(s.prestart_minutes)&&minute<mins(q.ends_at)+Number(s.postend_minutes));const schedule=schedulesOn(now.day).find(q=>q.room_code===room.code&&minute>=mins(q.starts_at)-Number(s.prestart_minutes)&&minute<mins(q.ends_at)+Number(s.postend_minutes));const target=adaptiveSetpoint(outsideNow(),schedule?.target_temp??s.default_setpoint);if(u.control_mode==='AUTO'&&(u.power_on!==active||(active&&u.target_temp!==target))){u.power_on=active;if(active)u.target_temp=target;u.manual_override_until=null;changes++}}
if(changes){logEvent('Otomasi',`${changes} unit disesuaikan dengan jadwal ${DAYS[now.day]} ${timeFormat()} WIB`,'Otomasi');save()}}
function mutateLocal(unit,action,value){const was=unit.power_on;switch(action){case'power':unit.power_on=!unit.power_on;break;case'power-on':unit.power_on=true;break;case'power-off':unit.power_on=false;break;case'temperature':unit.target_temp=clamp(Number(unit.target_temp)+Number(value),18,30);break;case'mode':unit.control_mode=value==='AUTO'?'AUTO':'MANUAL';break;case'hvac':{const vals=['COOL','DRY','FAN'];unit.hvac_mode=vals[(vals.indexOf(unit.hvac_mode||'COOL')+1)%vals.length];break}case'fan':{const vals=['AUTO','LOW','MED','HIGH'];unit.fan_mode=vals[(vals.indexOf(unit.fan_mode)+1)%vals.length];break}case'swing':unit.swing_on=!unit.swing_on;break;default:throw Error('Perintah tidak dikenal')}
if(action==='mode'&&value==='AUTO')unit.manual_override_until=null;
else{unit.control_mode='MANUAL';unit.manual_override_until=new Date(Date.now()+state.settings.override_minutes*60000).toISOString()}
unit.updated_at=new Date().toISOString();logEvent('Operator',`${unit.id} · ${action==='power'?(was?'DIMATIKAN':'DINYALAKAN'):action.toUpperCase()}${action==='temperature'?` → ${unit.target_temp}°C`:''} · override ${state.settings.override_minutes} menit`);save()}
async function sendCommand(id,action,value=null){if(!canEdit())return toast('Harus login sebagai operator atau admin.','error');const u=findUnit(id);if(!u)return;try{if(isCloud()){const map={power:['power',u.power_on?'false':'true'],temperature:['temperature',String(clamp(u.target_temp+Number(value),18,30))],mode:['mode',String(value)],fan:['fan',null],hvac:['hvac',null],swing:['swing',null],'power-on':['power','true'],'power-off':['power','false']};const [a,v]=map[action];const {error}=await state.supabase.rpc('issue_ac_command',{p_unit_id:id,p_action:a,p_value:v});if(error)throw error;await loadCloudData();toast(`Perintah ${id} berhasil disimpan ke Supabase.`)}else{mutateLocal(u,action,value);toast(`Pengaturan unit ${id} diperbarui pada browser ini.`)}rerender()}catch(e){toast(e.message,'error')}}
async function groupCommand(action){if(!canEdit())return toast('Login operator diperlukan.','error');const floor=$('#group-floor')?.value||'all';try{if(isCloud()){const {error}=await state.supabase.rpc('issue_group_command',{p_floor:floor==='all'?null:Number(floor),p_action:action});if(error)throw error;await loadCloudData()}else{let count=0;for(const u of state.units){const r=findRoom(u.room_code);if(r.is_24h||(floor!=='all'&&r.floor!==Number(floor)))continue;mutateLocal(u,action==='on'?'power-on':action==='off'?'power-off':'mode',action==='auto'?'AUTO':action==='manual'?'MANUAL':null);count++}logEvent('Operator',`Kontrol grup ${action.toUpperCase()} · ${count} unit (kecuali server)`)}toast(`Kontrol grup ${action.toUpperCase()} dikirim.`);rerender()}catch(e){toast(e.message,'error')}}
async function settingChange(key,value){if(!canEdit())return toast('Akses operator diperlukan.','error');const current={...state.settings};current[key]=value;try{if(isCloud()){const {error}=await state.supabase.from('automation_settings').update({[key]:value}).eq('id',1);if(error)throw error}else{state.settings=current;logEvent('Operator',`Aturan ${key} diubah menjadi ${value}`);save()}if(isCloud())await loadCloudData();rerender();toast('Pengaturan tersimpan.')}catch(e){toast(e.message,'error')}}
function scheduleModal(){const selectedDay=state.scheduleDay??(weekDay()||1);$('#modal-root').innerHTML=`<div class="modal-backdrop" data-action="close-modal"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div style="display:flex;justify-content:space-between;align-items:center"><h2 id="modal-title">Tambah Jadwal Kuliah</h2><button class="btn sm" data-action="close-modal">✕</button></div><p class="micro">Lengkapi mata kuliah, ruangan, waktu, dan target suhu.</p><form id="schedule-form"><label class="field-label">Mata kuliah</label><input class="input full" name="course" maxlength="90" required placeholder="Contoh: Rekayasa Perangkat Lunak"/><div class="form-grid"><div><label class="field-label">Hari</label><select class="select full" name="day_of_week">${DAYS.slice(1).map((d,i)=>`<option value="${i+1}" ${selectedDay===i+1?'selected':''}>${d}</option>`).join('')}</select></div><div><label class="field-label">Ruangan</label><select class="select full" name="room_code">${state.rooms.filter(r=>!r.is_24h).map(r=>`<option value="${r.code}">${r.code} · ${escapeHtml(r.name)}</option>`).join('')}</select></div><div><label class="field-label">Jam mulai</label><input class="input full" name="starts_at" type="time" value="08:00" required></div><div><label class="field-label">Jam selesai</label><input class="input full" name="ends_at" type="time" value="10:00" required></div><div><label class="field-label">Jumlah peserta</label><input class="input full" name="attendees" type="number" min="0" max="300" value="25" required></div><div><label class="field-label">Target suhu °C</label><input class="input full" name="target_temp" type="number" min="22" max="27" value="24" required></div></div><div class="modal-actions"><button type="button" class="btn" data-action="close-modal">Batal</button><button type="submit" class="btn primary">Simpan Jadwal</button></div></form></div></div>`}
async function addSchedule(form){const formdata=new FormData(form),entry=Object.fromEntries(formdata.entries());entry.day_of_week=Number(entry.day_of_week);entry.attendees=Number(entry.attendees);entry.target_temp=Number(entry.target_temp);entry.starts_at=normalizeClock(entry.starts_at);entry.ends_at=normalizeClock(entry.ends_at);entry.course=entry.course.trim();if(!entry.course||mins(entry.ends_at)<=mins(entry.starts_at))return toast('Jam selesai harus lebih besar dari jam mulai.','error');const room=findRoom(entry.room_code);if(entry.attendees>room.capacity)return toast(`Kapasitas ${room.code} maksimal ${room.capacity} peserta.`,'error');const conflict=schedulesOn(entry.day_of_week).some(s=>s.room_code===entry.room_code&&mins(entry.starts_at)<mins(s.ends_at)&&mins(entry.ends_at)>mins(s.starts_at));if(conflict)return toast('Ada jadwal yang bentrok pada ruangan dan hari yang sama.','error');try{if(isCloud()){const {error}=await state.supabase.from('class_schedules').insert({...entry,active:true});if(error)throw error;await loadCloudData()}else{state.schedules.push({...entry,id:globalThis.crypto?.randomUUID?.()||String(Date.now()),active:true});logEvent('Operator',`Jadwal ${entry.course} · ${entry.room_code} ${DAYS[entry.day_of_week]} ${entry.starts_at}–${entry.ends_at}`);save()}state.scheduleDay=entry.day_of_week;$('#modal-root').innerHTML='';rerender();toast('Jadwal kuliah berhasil disimpan.')}catch(e){toast(e.message,'error')}}
async function deleteSchedule(id){const s=state.schedules.find(s=>String(s.id)===String(id));if(!s||!confirm(`Hapus jadwal ${s.course} di ${s.room_code}?`))return;try{if(isCloud()){const {error}=await state.supabase.from('class_schedules').delete().eq('id',id);if(error)throw error;await loadCloudData()}else{state.schedules=state.schedules.filter(s=>String(s.id)!==String(id));logEvent('Operator',`Jadwal ${s.course} di ${s.room_code} dihapus`);save()}rerender();toast('Jadwal dihapus.')}catch(e){toast(e.message,'error')}}
async function refreshIdentity(){if(!state.supabase)return;const {data}=await state.supabase.auth.getUser();state.user=data?.user||null;state.memberRole=null;if(state.user){const {data:member}=await state.supabase.from('app_members').select('role').eq('user_id',state.user.id).maybeSingle();state.memberRole=member?.role||'viewer'}}
async function loadCloudData(){if(!state.supabase)return;const [rooms,units,sch,sett,logs]=await Promise.all([state.supabase.from('rooms').select('*').order('floor',{ascending:false}).order('code'),state.supabase.from('ac_units').select('*').order('id'),state.supabase.from('class_schedules').select('*').order('starts_at'),state.supabase.from('automation_settings').select('*').eq('id',1).maybeSingle(),state.user?state.supabase.from('event_logs').select('*').order('created_at',{ascending:false}).limit(150):Promise.resolve({data:[],error:null})]);for(const [key,r] of Object.entries({rooms,units,schedules:sch})){if(r.error)throw r.error;state[key]=r.data||[]}if(sett.error)throw sett.error;if(sett.data)state.settings=sett.data;if(!logs.error)state.logs=logs.data||[]}
function gateMessage(message){
  $('#app').innerHTML=`<div class="access-gate"><div class="access-gate-box"><span class="gate-symbol">❄</span><h1>Smart AC by RZKY Studio</h1><p>${escapeHtml(message)}</p><a class="btn primary" href="${loginUrl(location.href,CFG)}">Buka halaman login</a></div></div>`;
}
function redirectToLogin(){
  if(window.__redirectingToLogin)return;
  window.__redirectingToLogin=true;
  location.replace(loginUrl(location.href,CFG));
}
async function cloudInit(){
  if(!supportedHost()){
    gateMessage('Sistem harus diakses melalui subdomain HTTPS penyelamatharimu.my.id agar sesi login bisa digunakan bersama.');
    return false;
  }
  if(!CFG.supabaseUrl||!CFG.supabaseAnonKey){
    gateMessage('Supabase belum dikonfigurasi. Periksa config.js pada repository GitHub.');
    return false;
  }
  if(!hasSharedSession()){
    redirectToLogin();return false;
  }
  try{
    const {createClient}=await import('https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2/+esm');
    state.supabase=makeSharedSupabaseClient(createClient,CFG);
    state.mode='cloud';
    await refreshIdentity();
    if(!state.user){redirectToLogin();return false;}
    if(!['admin','operator','viewer'].includes(state.memberRole)){
      gateMessage('Akun terdaftar, tetapi belum mempunyai izin di app_members. Hubungi admin Supabase.');
      return false;
    }
    await loadCloudData();
    state.supabase.channel('smart-ac-campus').on('postgres_changes',{event:'*',schema:'public',table:'ac_units'},()=>loadCloudData().then(rerender).catch(console.error)).on('postgres_changes',{event:'*',schema:'public',table:'class_schedules'},()=>loadCloudData().then(rerender).catch(console.error)).on('postgres_changes',{event:'*',schema:'public',table:'automation_settings'},()=>loadCloudData().then(rerender).catch(console.error)).subscribe();
    state.supabase.auth.onAuthStateChange(event=>{
      if(event==='SIGNED_OUT')return redirectToLogin();
      if(event==='SIGNED_IN'||event==='USER_UPDATED'){
        setTimeout(()=>refreshIdentity().then(()=>loadCloudData()).then(rerender).catch(console.error),0);
      }
    });
    shell();return true;
  }catch(e){
    console.error('Supabase initialization:',e);
    gateMessage('Gagal memuat data dari Supabase. Periksa koneksi dan akses database, lalu refresh. Detail: '+(e?.message||''));
    return false;
  }
}
// event delegation, including elements rerendered after weather/realtime updates
$('#app').addEventListener('click',async e=>{const target=e.target.closest('[data-action],[data-tab]');if(!target)return;if(target.dataset.tab){state.hmiTab=target.dataset.tab;save();rerender();return}const action=target.dataset.action,id=target.dataset.id,value=target.dataset.value;switch(action){case'room':state.selectedRoom=id;state.plcSelectedId=unitsOf(id)[0]?.id||null;save();rerender();break;case'preview-now':state.previewDay=weekDay()||1;state.previewHour=currentHour();rerender();break;case'day':state.scheduleDay=Number(value);save();rerender();break;case'logfilter':state.logFilter=value;rerender();break;case'power':await sendCommand(id,'power');break;case'temperature':await sendCommand(id,'temperature',Number(value));break;case'toggle-mode':{const u=findUnit(id);await sendCommand(id,'mode',u.control_mode==='AUTO'?'MANUAL':'AUTO');break}case'cycle-control':await sendCommand(id,'hvac');break;case'fan':await sendCommand(id,'fan');break;case'swing':await sendCommand(id,'swing');break;case'group-on':await groupCommand('on');break;case'group-off':await groupCommand('off');break;case'group-auto':await groupCommand('auto');break;case'group-manual':await groupCommand('manual');break;case'add-schedule':scheduleModal();break;case'delete-schedule':await deleteSchedule(id);break;case'refresh-weather':await fetchWeather();toast(hasWeather()?'Cuaca berhasil diperbarui dari Open-Meteo.':'Layanan cuaca belum dapat diakses. Coba beberapa saat lagi.',hasWeather()?'success':'error');break;case'ack':toast('Notifikasi suhu telah ditandai dibaca.');if(!isCloud())logEvent('Alarm','Operator melakukan ACK semua alarm.');break;default:break}});
$('#app').addEventListener('change',async e=>{const el=e.target;if(el.id==='plc-unit-select'){state.plcSelectedId=el.value;rerender()}else if(el.id==='chart-room'){state.selectedRoom=el.value;state.plcSelectedId=unitsOf(el.value)[0]?.id||null;save();rerender()}else if(el.id==='preview-day'){state.previewDay=Number(el.value);rerender()}else if(el.id==='preview-hour'){state.previewHour=Number(el.value);rerender()}else if(el.id==='remote-device'){state.remoteId=el.value;state.plcSelectedId=el.value;save();rerender()}else if(el.dataset.setting){const key=el.dataset.setting;await settingChange(key,el.type==='checkbox'?el.checked:Number(el.value))}});
$('#app').addEventListener('input',e=>{if(e.target.id==='preview-hour'){state.previewHour=Number(e.target.value);rerender()}});
document.addEventListener('click',async e=>{const node=e.target.closest('[data-action]');if(!node)return;const action=node.dataset.action;if(action==='close-modal'){if(e.target===node||node.tagName==='BUTTON')$('#modal-root').innerHTML=''}else if(action==='logout'){try{if(state.supabase)await state.supabase.auth.signOut({scope:'global'});}finally{redirectToLogin();}}});
document.addEventListener('submit',async e=>{if(e.target.id==='schedule-form'){e.preventDefault();await addSchedule(e.target)}});
(async function bootstrap(){
  state.scheduleDay??=(weekDay()||1);
  state.previewDay??=(weekDay()||1);
  state.previewHour??=currentHour();
  $('#app').innerHTML='<div class="access-gate"><div class="access-gate-box"><span class="gate-symbol">❄</span><h1>Smart AC by RZKY Studio</h1><p>Memeriksa sesi login...</p></div></div>';
  if(!await cloudInit())return;
  connectPlc();fetchWeather();
  const checkSession=()=>{if(!hasSharedSession())redirectToLogin();};
  window.addEventListener('focus',checkSession);
  document.addEventListener('visibilitychange',()=>{if(!document.hidden)checkSession();});
  setInterval(checkSession,3000);
  setInterval(()=>{const c=$('#nav-clock');if(c)c.textContent=timeFormat()+' WIB';if(PAGE==='dashboard')rerender()},60_000);
  setInterval(fetchWeather,15*60_000);
})();
